public class ErpSyncFinalizer implements Finalizer {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext fc) {
        FB_Job_Log__c log = new FB_Job_Log__c();
        log.Job_Name__c = 'ErpAccountSyncJob';
        log.Attempt__c = attempt;

        Exception ex = fc.getException();
        if (ex == null) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';
            String msg = ex.getMessage();
            if (msg != null && msg.length() > 255) {
                msg = msg.left(255);
            }
            log.Error__c = msg;

            if (attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }

        insert log;
    }
}
