public virtual class Application {

    public static final fflib_Application.UnitOfWorkFactory UnitOfWork = new UnitOfWorkFactoryImpl();
    public static final fflib_Application.ServiceFactory Service = new ServiceFactoryImpl();
    public static final fflib_Application.SelectorFactory Selector = new SelectorFactoryImpl();
    public static final fflib_Application.DomainFactory Domain = new DomainFactoryImpl();

    private class UnitOfWorkFactoryImpl extends fflib_Application.UnitOfWorkFactory {
        public override fflib_ISObjectUnitOfWork newInstance() {
            return new fflib_SObjectUnitOfWork(new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            });
        }
    }

    private class ServiceFactoryImpl extends fflib_Application.ServiceFactory {
        public override Object getService(Type type) {
            if (type == IAccountsService.class) {
                return new AccountsServiceImpl();
            }
            return super.getService(type);
        }
    }

    private class SelectorFactoryImpl extends fflib_Application.SelectorFactory {
        public override fflib_SObjectSelector newInstance(Schema.SObjectType sobjectType) {
            if (sobjectType == Account.SObjectType) {
                return new AccountsSelector();
            }
            if (sobjectType == Contact.SObjectType) {
                return new ContactsSelector();
            }
            return super.newInstance(sobjectType);
        }
    }

    private class DomainFactoryImpl extends fflib_Application.DomainFactory {
        public override fflib_IDomain newInstance(Set<Id> recordIds) {
            List<Account> accounts = ((AccountsSelector) Application.Selector.newInstance(Account.SObjectType)).selectById(recordIds);
            return new Accounts.Constructor().construct((List<SObject>) accounts);
        }
    }
}
