            return new List<Account>();
        }
        return (List<Account>) Database.query(buildQuery(false));
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        return (List<Account>) Database.query(buildQuery(true));
    }

    private String buildQuery(Boolean includeContacts) {
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            fieldNames.add(f.getDescribe().getName());
        }
        String fieldList = String.join(fieldNames, ', ');

        String selectClause;
        if (includeContacts) {
            List<String> contactFieldNames = new List<String>();
            for (Schema.SObjectField f : new ContactsSelector().getSObjectFieldList()) {
                contactFieldNames.add(f.getDescribe().getName());
            }
            selectClause = fieldList + ',(SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts)';
        } else {
            selectClause = fieldList;
        }

        // WITH USER_MODE forces the platform to enforce the running user's object,
        // field and sharing access, so a user who cannot read a selected field gets
        // a QuerySecurityException instead of data.
        return 'SELECT ' + selectClause + ' FROM Account WITH USER_MODE WHERE Id IN :accountIds';
    }

    /**
     * Fields that make up the Account field set "Credit_Review".
     *
     * Apex has no runtime introspection for field sets (the Schema namespace does not
     * expose them), so the field set members must be mirrored here and kept in
     * lockstep with the field set by the admins/developers.
     */
    private List<Schema.SObjectField> getCreditReviewFieldSetFields() {
        return new List<Schema.SObjectField>{
            Account.AnnualRevenue,
            Account.Rating
        };
    }
