```apex
public with sharing class ErpCustomerSync {

    private static final Integer MAX_CALLOUTS_PER_TRANSACTION = 100;

    /**
     * Enqueues a single Queueable that will fire one POST per account.
     * If the number of accounts exceeds the per-transaction callout limit,
     * the Queueable chains itself for the remaining records.
     */
    public static void enqueue(List<Account> accounts) {
        List<Id> ids = new List<Id>();
        List<String> names = new List<String>();
        List<String> countries = new List<String>();

        for (Account a : accounts) {
            ids.add(a.Id);
            names.add(a.Name);
            countries.add(a.BillingCountry);
        }

        System.enqueueJob(new SyncJob(ids, names, countries, 0));
    }

    public class SyncJob implements Queueable {

        private final List<Id> ids;
        private final List<String> names;
        private final List<String> countries;
        private final Integer offset;

        public SyncJob(List<Id> ids, List<String> names, List<String> countries, Integer offset) {
            this.ids = ids;
            this.names = names;
            this.countries = countries;
            this.offset = offset;
        }

        public void execute(QueueableContext ctx) {
            Integer end = Math.min(offset + MAX_CALLOUTS_PER_TRANSACTION, ids.size());

            for (Integer i = offset; i < end; i++) {
                postToErp(ids[i], names[i], countries[i]);
            }

            if (end < ids.size()) {
                System.enqueueJob(new SyncJob(ids, names, countries, end));
            }
        }

        private void postToErp(Id accountId, String name, String country) {
            Map<String, Object> customer = new Map<String, Object>{
                'salesforceId' => accountId,
                'name'         => name,
                'country'      => String.isBlank(country) ? null : country
            };

            HttpRequest req = new HttpRequest();
            req.setEndpoint('callout:ERP/api/customers');
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(JSON.serialize(new List<Map<String, Object>>{ customer }));
            req.setTimeout(60000);

            // Error handling and retries are out of scope for this ticket.
            new Http().send(req);
        }
    }
}
