public class CaseSurveyJob implements Queueable {
    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        Case c = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
        ];

        if (c.ContactId == null) {
            return;
        }

        insert new Task(
            WhatId       = c.Id,
            WhoId        = c.ContactId,
            Subject      = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status       = 'Not Started'
        );
    }

    /**
     * Inner class that chains additional CaseSurveyJob enqueues when the
     * eligible-case count exceeds the 50 Queueable-jobs-per-transaction limit.
     * Each round enqueues up to 49 worker jobs plus one more Continuation
     * (if needed), keeping every transaction within the governor limit.
     */
    public class Continuation implements Queueable {
        private final List<Id> caseIds;

        public Continuation(List<Id> caseIds) {
            this.caseIds = caseIds;
        }

        public void execute(QueueableContext context) {
            if (caseIds.size() <= 50) {
                for (Id caseId : caseIds) {
                    System.enqueueJob(new CaseSurveyJob(caseId));
                }
            } else {
                Integer jobsThisRound = 49;
                for (Integer i = 0; i < jobsThisRound; i++) {
                    System.enqueueJob(new CaseSurveyJob(caseIds[i]));
                }
                System.enqueueJob(new CaseSurveyJob.Continuation(
                    caseIds.subList(jobsThisRound, caseIds.size())
                ));
            }
        }
    }
}
