```js
import { LightningElement, api, track } from 'lwc';

let uniqueId = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    @track _value = '';
    @track _options = [];
    @track _activeIndex = 0;
    _idPrefix;

    constructor() {
        super();
        uniqueId += 1;
        this._idPrefix = `status-listbox-${uniqueId}`;
    }

    @api
    get value() {
        return this._value;
    }

    set value(val) {
        const prev = this._value;
        this._value = val;
        if (val !== prev) {
            const idx = this._options.findIndex((o) => o.value === val);
            this._activeIndex = idx !== -1 ? idx : 0;
        }
    }

    @api
    get options() {
        return this._options;
    }

    set options(val) {
        this._options = val || [];
        const idx = this._options.findIndex((o) => o.value === this._value);
        this._activeIndex = idx !== -1 ? idx : 0;
    }

    get optionItems() {
        return this._options.map((opt, i) => ({
            id: `${this._idPrefix}-option-${i}`,
            value: opt.value,
            label: opt.label,
            isSelected: opt.value === this._value
        }));
    }

    get activeDescendantId() {
        if (this._options.length === 0) {
            return null;
        }
        return `${this._idPrefix}-option-${this._activeIndex}`;
    }

    handleKeydown(event) {
        const { key } = event;
        const len = this._options.length;

        if (len === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._activeIndex < len - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = len - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectActive();
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const li = event.currentTarget;
        const value = li.dataset.value;
        this._selectOption(value);
    }

    _selectActive() {
        const len = this._options.length;
        if (this._activeIndex >= 0 && this._activeIndex < len) {
            this._selectOption(this._options[this._activeIndex].value);
        }
    }

    _selectOption(value) {
        if (value === this._value) {
            return;
        }
        this._value = value;
        this._activeIndex = this._options.findIndex((o) => o.value === value);
        this.dispatchEvent(
            new CustomEvent('change', {
                bubbles: true,
                detail: { value: value }
            })
        );
    }
}
