     * edit access, as reported by the UserRecordAccess virtual object.
     *
     * @param recordIds  Up to 2,000 record IDs (may span multiple objects).
     * @return           A set of IDs that the current user can edit.
     *                   Never returns null; returns an empty set for null/empty input.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editable = new Set<Id>();
        List<Id> idList = new List<Id>(recordIds);

        // Chunk to stay within platform limits on IN clause size for virtual objects
        Integer batchSize = 500;
        for (Integer i = 0; i < idList.size(); i += batchSize) {
            Integer end = Math.min(i + batchSize, idList.size());
            List<Id> batch = idList.sublist(i, end);

            for (UserRecordAccess ura : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :batch
                  AND HasEditAccess = true
            ]) {
                editable.add(ura.RecordId);
            }
        }

        return editable;
    }
}
