trigger CaseTrigger on Case(
    before insert,
    after insert,
    before update,
    after update,
    before delete,
    after delete,
    after undelete
) {
    MetadataTriggerHandler th = new MetadataTriggerHandler();
    if (Trigger.isBefore && Trigger.isInsert) {
        th.beforeInsert(Trigger.new);
    }
    if (Trigger.isAfter && Trigger.isInsert) {
        th.afterInsert(Trigger.new);
    }
    if (Trigger.isBefore && Trigger.isUpdate) {
        th.beforeUpdate(Trigger.new, Trigger.old);
    }
    if (Trigger.isAfter && Trigger.isUpdate) {
        th.afterUpdate(Trigger.new, Trigger.old);
    }
    if (Trigger.isBefore && Trigger.isDelete) {
        th.beforeDelete(Trigger.old);
    }
    if (Trigger.isAfter && Trigger.isDelete) {
        th.afterDelete(Trigger.old);
    }
    if (Trigger.isAfter && Trigger.isUndelete) {
